contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint dummy) public {
        require(dummy < 1 ether);
        uint balBefore = address(c).balance;
        uint p0 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        bool reverted;
        uint ret;
        uint256 v = c.pastBlockTime(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            ret = v;
        }
        assert(!reverted && ret == p0 && ret <= block.timestamp && address(c).balance == balBefore);
    }
}

