// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 dummy) internal {
        dummy = bound(dummy, 0, 0);
        uint balBefore = address(c).balance;
        uint256 p0;
        try c.pastBlockTime() returns (uint256 __r) { p0 = __r; } catch { return; }
        bool reverted;
        uint ret;
        try c.pastBlockTime() returns (uint v) {
            reverted = false;
            ret = v;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && ret == p0 && ret <= block.timestamp && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
